const translations = { 'English': { 'Mostrando': 'Showing', 'vehículos': 'vehicles' }, 'Portugues': { 'Mostrando': 'Mostrando', 'vehículos': 'veículos' }, 'Italiano': { 'Mostrando': 'Mostrando', 'veicoli': 'veicoli' }, 'Frances': { 'Mostrando': 'Affichage', 'vehículos': 'véhicules' }, 'Deutsch': { 'Mostrando': 'Anzeige', 'vehículos': 'Fahrzeuge' } }; 
const pathParts = window.location.pathname.split('/'); 
const lang = pathParts.find(p => ['English', 'Portugues', 'Italiano', 'Frances', 'Deutsch'].includes(p)) || 'Español'; 
if (lang !== 'Español') { 
  document.body.querySelectorAll('*').forEach(el => { 
    if (el.children.length === 0 && (el.textContent.includes('Mostrando') || el.textContent.includes('vehículos'))) { 
      el.textContent = el.textContent.replace('Mostrando', translations[lang]['Mostrando'] || 'Mostrando').replace('vehículos', translations[lang]['vehículos'] || 'veicoli'); 
    } 
  }); 
}
const h = document.createElement('div');
h.style.position = 'absolute';
h.style.border = '4px solid #00FFFF';
h.style.zIndex = '9999';
h.style.pointerEvents = 'none';
h.style.boxSizing = 'border-box';
const c1 = document.querySelector('otto-web-grid-header .header__cell:nth-child(1)');
const c2 = document.querySelector('otto-web-grid-header .header__cell:nth-child(2)');
const lr = Array.from(document.querySelectorAll('otto-web-grid-row')).find(r => r.textContent.includes('0030-LFX'));
if (c1 && c2 && lr) {
  const r1 = c1.getBoundingClientRect();
  const r2 = c2.getBoundingClientRect();
  const r3 = lr.getBoundingClientRect();
  h.style.top = (r1.top - 4) + 'px';
  h.style.left = (r1.left - 4) + 'px';
  h.style.width = (r2.right - r1.left + 8) + 'px';
  h.style.height = (r3.bottom - r1.top + 8) + 'px';
  document.body.appendChild(h);
}
